def _solve_single_real(z0_m, z_grid_m, rho_grid, T_grid, m_kg,
                       CD_subsonic, CD_transonic, CD_final_subsonic,
                       A_subsonic_m2, A_supersonic_m2,
                       mach_subsonic_max, mach_supersonic_min):
    if z0_m <= 1.0:
        # Degenerate: essentially no fall. Return zeros, not an error.
        return {"x": np.array([0.0]), "v": np.array([0.0]), "a": np.array([0.0]),
                "mach": np.array([0.0]), "regime": ["subsonic"],
                "max_v": 0.0, "max_abs_a": 0.0, "max_abs_a_in_g": 0.0,
                "z0_m": z0_m}

    rho_lookup = lambda alt: float(np.interp(alt, z_grid_m, rho_grid))
    T_lookup = lambda alt: float(np.interp(alt, z_grid_m, T_grid))
    a_sound = lambda alt: np.sqrt(GAMMA * R_SPECIFIC * T_lookup(alt))

    regime = {"cur": "subsonic"}

    def cd_a_of(v, alt):
        """Return (CD, A) for a given speed at a given altitude,
        transitioning the regime state machine in place."""
        M = v / a_sound(alt)
        if regime["cur"] == "final_subsonic":
            return CD_final_subsonic, A_supersonic_m2
        if regime["cur"] == "supersonic" and M >= mach_supersonic_min:
            pass  # stay supersonic
        elif regime["cur"] == "transonic" and M >= mach_subsonic_max and M < mach_supersonic_min:
            pass  # stay transonic
        elif regime["cur"] == "subsonic" and M < mach_subsonic_max:
            pass  # stay subsonic
        # Now handle all transitions in one go based on current M, ignoring
        # where we came from (one-way subsonic -> transonic -> supersonic ->
        # final_subsonic, no downward transitions between subsonic and
        # transonic/supersonic once left; but transonic CAN drop back to
        # final_subsonic if M falls below mach_subsonic_max).
        if M >= mach_supersonic_min:
            regime["cur"] = "supersonic" if regime["cur"] != "final_subsonic" else regime["cur"]
        elif M >= mach_subsonic_max:
            if regime["cur"] not in ("supersonic", "final_subsonic"):
                regime["cur"] = "transonic"
        else:
            if regime["cur"] in ("transonic", "supersonic"):
                regime["cur"] = "final_subsonic"
        if regime["cur"] == "subsonic":
            return CD_subsonic, A_subsonic_m2
        if regime["cur"] == "transonic":
            return CD_transonic, A_subsonic_m2
        if regime["cur"] == "supersonic":
            return CD_transonic, A_supersonic_m2
        return CD_final_subsonic, A_supersonic_m2

