        if M >= mach_supersonic_min:
            if regime2["cur"] != "final_subsonic":
                regime2["cur"] = "supersonic"
        elif M >= mach_subsonic_max:
            if regime2["cur"] not in ("supersonic", "final_subsonic"):
                regime2["cur"] = "transonic"
        else:
            if regime2["cur"] in ("transonic", "supersonic"):
                regime2["cur"] = "final_subsonic"
